using InventorySystem.Domain.Entities; using InventorySystem.Infrastructure.Persistence; using InventorySystem.Infrastructure.Services; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace InventorySystem.API.Controllers;
[ApiController][Route("api/auth")] public class AuthController(UserManager<AppUser> users,SignInManager<AppUser> signIn,TokenService tokens,AppDbContext db) : ControllerBase { public record LoginRequest(string Email,string Password); public record RegisterRequest(string Email,string Password,string FullName,string? Role); public record RefreshRequest(string RefreshToken); private static readonly string[] ValidRoles=["Admin","Manager","Cashier"]; [HttpPost("login")] public async Task<IActionResult> Login(LoginRequest r){ var u=await users.FindByEmailAsync(r.Email); if(u is null) return Unauthorized(new{error="Invalid credentials."}); var check=await signIn.CheckPasswordSignInAsync(u,r.Password,false); if(!check.Succeeded) return Unauthorized(new{error="Invalid credentials."}); return Ok(await IssueTokensAsync(u)); } [HttpPost("register")] public async Task<IActionResult> Register(RegisterRequest r){ var role=ValidRoles.FirstOrDefault(v=>v.Equals(r.Role,StringComparison.OrdinalIgnoreCase))??"Cashier"; if(r.Role is not null&&!ValidRoles.Any(v=>v.Equals(r.Role,StringComparison.OrdinalIgnoreCase))) return BadRequest(new{error="Invalid role."}); if(!role.Equals("Cashier",StringComparison.OrdinalIgnoreCase)&&!User.IsInRole("Admin")) return Forbid(); var u=new AppUser{UserName=r.Email,Email=r.Email,FullName=r.FullName}; var result=await users.CreateAsync(u,r.Password); if(!result.Succeeded) return BadRequest(result.Errors); await users.AddToRoleAsync(u,role); return Ok(await IssueTokensAsync(u)); } [HttpPost("refresh")] public async Task<IActionResult> Refresh(RefreshRequest r){ var stored=await db.RefreshTokens.Include(x=>x.User).FirstOrDefaultAsync(x=>x.Token==r.RefreshToken); if(stored is null||stored.Revoked||stored.Expires<=DateTime.UtcNow) return Unauthorized(new{error="Invalid refresh token."}); var user=stored.User; if(user is null) return Unauthorized(new{error="Invalid refresh token."}); stored.Revoked=true; db.RefreshTokens.Update(stored); await db.SaveChangesAsync(); return Ok(await IssueTokensAsync(user)); } [HttpPost("revoke")] public async Task<IActionResult> Revoke(RefreshRequest r){ var stored=await db.RefreshTokens.FirstOrDefaultAsync(x=>x.Token==r.RefreshToken); if(stored is not null){ stored.Revoked=true; await db.SaveChangesAsync(); } return Ok(); } private async Task<object> IssueTokensAsync(AppUser u){ var rt=new RefreshToken{UserId=u.Id,Token=tokens.GenerateRefreshToken(),Expires=DateTime.UtcNow.AddDays(7)}; db.RefreshTokens.Add(rt); await db.SaveChangesAsync(); return new{token=await tokens.GenerateTokenAsync(u),refreshToken=rt.Token}; } }
